    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_hops_with_proxy_pc(self):
        state_hops = {
            RtgController3.not_connected: {
                RtgController3.linux: RtgController3.unix_local,
                RtgController3.argon: RtgController3.unix_local,
                RtgController3.uesim: RtgController3.unix_local,
            },
            RtgController3.linux: {
                RtgController3.not_connected: RtgController3.proxy_pc,
                RtgController3.unix_local: RtgController3.proxy_pc,
                RtgController3.unix_local_root: RtgController3.proxy_pc,
            },
            RtgController3.argon: {
                RtgController3.unix_local: RtgController3.linux,
                RtgController3.unix_local_root: RtgController3.linux,
                RtgController3.proxy_pc: RtgController3.linux,
                RtgController3.not_connected: RtgController3.linux,
                RtgController3.uesim: RtgController3.linux,
            },
            RtgController3.uesim: {
                RtgController3.unix_local: RtgController3.linux,
                RtgController3.unix_local_root: RtgController3.linux,
                RtgController3.proxy_pc: RtgController3.linux,
                RtgController3.not_connected: RtgController3.linux,
                RtgController3.argon: RtgController3.linux,
            },
            RtgController3.unix_local: {
                RtgController3.linux: RtgController3.proxy_pc,
                RtgController3.argon: RtgController3.proxy_pc,
                RtgController3.uesim: RtgController3.proxy_pc,
            },
            RtgController3.proxy_pc: {
                RtgController3.argon: RtgController3.linux,
                RtgController3.unix_local_root: RtgController3.unix_local,
                RtgController3.uesim: RtgController3.linux,
            },
            RtgController3.unix_local_root: {
                RtgController3.argon: RtgController3.unix_local,
                RtgController3.uesim: RtgController3.unix_local,
                RtgController3.linux: RtgController3.unix_local,
            },
        }
        self.__def_add_next_hop_for_dsp_list(state_hops, is_proxy_connection=True)
        return state_hops

