    def _get_packages_for_state(self, state, observer):
        """
        Get available packages contain cmds and events for each state.

        :param state: device state.
        :param observer: observer type, available: cmd, events
        :return: available cmds or events for specific device state.
        """
        available = super(RtgController3, self)._get_packages_for_state(state, observer)

        if not available:
            if state == RtgController3.linux:
                available = {RtgController3.cmds: ['moler.cmd.unix', 'ta_moler.cmd.shared.nokiaunix',
                                                   'ta_moler.cmd.shared.enblinux',
                                                   'ta_moler.cmd.fzmconsole.linux', 'ta_moler.cmd.rtg_ctrl.linux'],
                             RtgController3.events: ['moler.events.shared', 'moler.events.unix',
                                                     'ta_moler.events.fzmconsole', 'ta_moler.events.rtg_ctrl']}
            elif state == RtgController3.argon:
                available = {RtgController3.cmds: ['ta_moler.cmd.shared.argon', 'ta_moler.cmd.fzmconsole.argon'],
                             RtgController3.events: ['moler.events.shared', 'moler.events.unix',
                                                     'ta_moler.events.fzmconsole']}
            elif re.match(r"DSP\d", state):
                available = self.__get_dsp_packages()
            elif state == RtgController3.uesim:
                available = {RtgController3.cmds: ['ta_moler.cmd.rtg_ctrl.uesim'],
                             RtgController3.events: ['moler.events.shared']}
            if available:
                return available[observer]

        return available

    def __update_state_prompts(self, state_prompts):
        for dsp in RtgController3.dsps:
            state_prompts[dsp] = self._configurations[RtgController3.connection_hops][RtgController3.linux][dsp][
                "command_params"]["expected_prompt"]

    @staticmethod
    def __def_add_next_hop_for_dsp_list(state_hops, is_proxy_connection):
        dsp_elements = {
            RtgController3.unix_local: RtgController3.linux,
            RtgController3.unix_local_root: RtgController3.linux,
            RtgController3.not_connected: RtgController3.linux,
            RtgController3.argon: RtgController3.linux,
            RtgController3.uesim: RtgController3.linux
        }

        if is_proxy_connection:
            dsp_elements[RtgController3.proxy_pc] = RtgController3.linux

        dsp_number = 0
        for dsp in RtgController3.dsps:
            if is_proxy_connection:
                state_hops[RtgController3.unix_local][dsp] = RtgController3.proxy_pc
                state_hops[RtgController3.proxy_pc][dsp] = RtgController3.linux
            else:
                state_hops[RtgController3.unix_local][dsp] = RtgController3.linux
            state_hops[RtgController3.not_connected][dsp] = RtgController3.unix_local
            state_hops[RtgController3.unix_local_root][dsp] = RtgController3.unix_local
            state_hops[RtgController3.uesim][dsp] = RtgController3.linux
            state_hops[RtgController3.argon][dsp] = RtgController3.linux
            state_hops[dsp] = {}
            state_hops[dsp].update(dsp_elements)
            rest_dsps = list(RtgController3.dsps)
            rest_dsps.pop(dsp_number)
            dsp_number += 1
            for other_dsp in rest_dsps:
                state_hops[dsp][other_dsp] = RtgController3.linux

    @staticmethod
    def __update_transitions_for_dsps(transitions):
        for dsp in RtgController3.dsps:
            transitions[RtgController3.linux][dsp] = ACTION_TO_CHANGE_STATE
            transitions[dsp] = {RtgController3.linux: ACTION_TO_CHANGE_STATE}

    @staticmethod
    def __get_dsp_packages():
        return {RtgController3.cmds: ['ta_moler.cmd.rtg_ctrl.dsp'],
                RtgController3.events: ['moler.events.shared']}

    @staticmethod
    def __generate_change_from_dsp_sm_configuration(dsp_number):
        return {
            RtgController3.linux: {
                "execute_command": "exit_mmi",  # using command
                "command_params":
                    {  # with parameters
                        "prompt": RtgController3.__generate_dsp_prompt(dsp_number),
                        "expected_prompt": r'toor4nsn@fzm-lsp-k2:.*#\s*',
                    },
                "required_command_params": []
            }
        }

    def __generate_change_to_dsp_sm_configuration(self, dsp_number):
        return {  # to
            "execute_command": "mmi",
            "command_params": {
                "expected_prompt": self.__generate_dsp_prompt(dsp_number),
                "dsp_number": dsp_number,
            },
            "required_command_params": []
        }

    def __update_dsp_list_configuration(self, config):
        dsp_number = 1
        for dsp in RtgController3.dsps:
            config[RtgController3.connection_hops][RtgController3.linux][dsp] = \
                self.__generate_change_to_dsp_sm_configuration(dsp_number=dsp_number)
            config[RtgController3.connection_hops][dsp] = \
                self.__generate_change_from_dsp_sm_configuration(dsp_number=dsp_number)
            dsp_number += 1

    @staticmethod
    def __generate_dsp_prompt(dsp_number):
        return rf"Core\s*(?:123\.)?{dsp_number}\s*>"
